<script setup lang="ts">import entities from '../../data/entities.json';import {computed} from 'vue';const p=defineProps<{id:string}>();const e=computed(()=>entities.entities.find((x:any)=>x.id===p.id))</script><template><div v-if="e" class="lore-card" :class="`status-${e.status}`"><strong>{{e.name}}</strong> <span class="lore-status">{{e.status}}</span><dl><dt>Type</dt><dd>{{e.type}}</dd><dt>Origin</dt><dd>{{e.origin_location}}</dd><dt>Initial population</dt><dd>{{e.initial_population.toLocaleString()}}</dd></dl></div><div v-else class="lore-card">Unknown entity: {{id}}</div></template>
